<template>
  <div id="app">
    <!-- If not authenticated, show the Login component -->
    <Login v-if="!isAuthenticated" @login-success="handleLoginSuccess" />
    <!-- If authenticated, show navigation and the rest of the app -->
    <div v-else>
      <nav>
        <router-link to="/">Home</router-link>
        <router-link to="/youtube">YouTube Uploader</router-link>
        <router-link to="/twitter">Twitter Uploader</router-link>
        <button @click="logout" style="margin-left:20px; color:#ff4d4d;">Logout</button>
      </nav>
      <router-view />
    </div>
  </div>
</template>

<script>
import Login from "./views/Login.vue"
import Auth0 from 'auth0-js'

export default {
  name: "App",
  components: {
    Login
  },
  data() {
    return {
      isAuthenticated: false,
      user: null,
      auth0Client: null,
      error: null
    }
  },
  methods: {
    handleLoginSuccess(userData) {
      // This event handler is triggered after a successful login from the Login component.
      this.user = userData
      this.isAuthenticated = true
    },
    logout() {
      localStorage.removeItem("idToken")
      localStorage.removeItem("expiresAt")
      localStorage.removeItem("userEmail")
      this.isAuthenticated = false
      this.user = null
      window.location.reload()
    },
    setSession(authResult) {
      // Save tokens and expiration into localStorage.
      localStorage.setItem("idToken", authResult.idToken)
      let expiresAt = new Date().getTime() + authResult.expiresIn * 1000
      localStorage.setItem("expiresAt", expiresAt)
      localStorage.setItem("userEmail", authResult.idTokenPayload.email)
      this.user = authResult.idTokenPayload
      this.isAuthenticated = true
    }
  },
  mounted() {
    // Create an auth0Client instance.
    this.auth0Client = new Auth0.WebAuth({
      domain: "login.golingoapp.com",         // e.g., login.golingoapp.com
      clientID: "qXplijQBTBiXyYsEkx0YP1lLXf0X8b2Z",           // e.g., CAbDNnKwXbemnPuMqg6R7ElN4F77IRA3
      responseType: "token id_token",
      redirectUri: window.location.origin,
      realm: "Username-Password-Authentication"  // The database connection name
    })

    // Check if we're returning from Auth0 with tokens in the hash.
    if (window.location.hash && window.location.hash.includes("access_token")) {
      this.auth0Client.parseHash((err, authResult) => {
        if (authResult && authResult.accessToken && authResult.idToken) {
          window.location.hash = ""  // Remove hash from URL
          this.setSession(authResult)
        } else if (err) {
          console.error("Error parsing hash:", err)
          this.error = err
        }
      })
    } else {
      // If no token is in the URL, check localStorage for an existing valid session.
      const idToken = localStorage.getItem("idToken")
      const expiresAt = localStorage.getItem("expiresAt")
      if (idToken && new Date().getTime() < expiresAt) {
        this.user = { email: localStorage.getItem("userEmail") }
        this.isAuthenticated = true
      }
    }
  }
}
</script>

