<template>
  <div id="login-container">
    <h2>Login</h2>
    <input type="email" v-model="email" placeholder="Enter your email" required />
    <input type="password" v-model="password" placeholder="Enter your password" required />
    <div class="button-group">
      <button @click="login">Login</button>
      <button @click="register">Register</button>
    </div>
    <div v-if="errorMessage" class="error">{{ errorMessage }}</div>
  </div>
</template>

<script>
import Auth0 from 'auth0-js'

export default {
  name: 'Login',
  data() {
    return {
      email: '',
      password: '',
      errorMessage: '',
      // Initialize auth0Client from auth0.js (using your tenant details)
      auth0Client: new Auth0.WebAuth({
        domain: 'login.golingoapp.com',      // e.g., login.golingoapp.com
        clientID: 'qXplijQBTBiXyYsEkx0YP1lLXf0X8b2Z',         // e.g., CAbDNnKwXbemnPuMqg6R7ElN4F77IRA3
        responseType: 'token id_token',
        redirectUri: window.location.origin,
        // Use the following realm for database connections
        realm: 'Username-Password-Authentication'
      })
    }
  },
  methods: {
    login() {
      if (!this.email || !this.password) {
        this.errorMessage = 'Please enter both email and password.'
        return
      }

      // Use the resource owner password grant (not recommended for public clients unless safe and enabled)
      this.auth0Client.login(
        {
          realm: 'Username-Password-Authentication',
          username: this.email,
          password: this.password,
          scope: 'openid profile email'
        },
        (err, authResult) => {
          if (err) {
            this.errorMessage = err.description || err.message
            console.error(err)
            return
          }
          if (authResult && authResult.idTokenPayload) {
            // Save tokens & user info locally (for example purposes; you can use vuex or provide/inject)
            localStorage.setItem('idToken', authResult.idToken)
            let expiresAt = new Date().getTime() + 86400000 // 24 hours
            localStorage.setItem('expiresAt', expiresAt)
            localStorage.setItem('userEmail', authResult.idTokenPayload.email)
            this.$emit('login-success', authResult.idTokenPayload)
          }
        }
      )
    },
    register() {
      if (!this.email || !this.password) {
        this.errorMessage = 'Please enter both email and password to register.'
        return
      }

      // Use auth0Client.signup to create a new user in your database connection.
      this.auth0Client.signup(
        {
          connection: 'Username-Password-Authentication',
          email: this.email,
          password: this.password
        },
        (err, result) => {
          if (err) {
            this.errorMessage = err.description || err.message
            console.error(err)
          } else {
            alert('Registration successful! Please log in now.')
          }
        }
      )
    }
  }
}
</script>

